'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// FIXTURES //

var decimalDecimal = require( './fixtures/julia/decimal_decimal.json' );


// VARIABLES //

var quantile = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( quantile instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof quantile, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', opts, function test( t ) {
	var y = quantile( NaN, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = quantile( 0.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a number outside `[0,1]` for `p` and a finite `k`, the function returns `NaN`', opts, function test( t ) {
	var y = quantile( 2.2, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = quantile( -0.2, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a negative `k`, the function always returns `NaN`', opts, function test( t ) {
	var y;

	y = quantile( 0.5, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = quantile( 0.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = quantile( 0.5, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if `k` equals `0`, the function evaluates a degenerate distribution centered at `0`', opts, function test( t ) {
	var y;

	y = quantile( 0.3, 0.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = quantile( 0.9, 0.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = quantile( 1.1, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = quantile( -0.1, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function evaluates the quantile for `x` given degrees of freedom `k`', opts, function test( t ) {
	var expected;
	var p;
	var k;
	var y;
	var i;

	expected = decimalDecimal.expected;
	p = decimalDecimal.p;
	k = decimalDecimal.k;
	for ( i = 0; i < p.length; i++ ) {
		y = quantile( p[i], k[i] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 195 ), true, 'returns expected value' );
	}
	t.end();
});
